import re
from datetime import datetime

with open('./doc/Laboratory.md', 'r') as f:
    lab = f.read()

# Extract patient-creatinine pairs
# Pattern: patient XXXXXXX, ... creatinine.*([\d.]+)
pattern = r'[Pp]atient\s+(\d{7})[^c]*?(?:creatine|creatinine).*?([\d.]+)\s*mg/dL'
creatinine_data = re.findall(pattern, lab, re.IGNORECASE)
print(f'Found {len(creatinine_data)} creatinine entries')
for c in creatinine_data[:10]:
    print(f'  Lab ID {c[0]}, Creatinine: {c[1]} mg/dL')

# Map to 6-digit patient IDs (last 6 digits)
patient_creatinine = {}
for lab_id, creat in creatinine_data:
    patient_id = lab_id  # The 7-digit ID is the actual ID
    if patient_id not in patient_creatinine:
        patient_creatinine[patient_id] = []
    patient_creatinine[patient_id].append(float(creat))

# Get the creatinine values and find abnormal ones
abnormal_threshold = 1.2  # Based on previous observation
abnormal_patients = {}
for pid, values in patient_creatinine.items():
    for v in values:
        if v > abnormal_threshold:
            if pid not in abnormal_patients:
                abnormal_patients[pid] = []
            abnormal_patients[pid].append(v)

print(f'\nAbnormal entries (>1.2 mg/dL): {len(abnormal_patients)} patients')
for pid, vals in list(abnormal_patients.items())[:10]:
    print(f'  {pid}: {vals}')

